import{z as s,x as A,o as n,c as C,q as B,j as i,D as r,d as E,s as o,S as l,b as t}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"单信号评估：IC、换手与成本会师","description":"","frontmatter":{"title":"单信号评估：IC、换手与成本会师","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/single-signal-eval.md","filePath":"quant/single-signal-eval.md","lastUpdated":1791063341000}'),d={name:"quant/single-signal-eval.md"};function I(p,a,h,m,u,c){const e=A("Mermaid");return n(),C("div",null,[a[2]||(a[2]=B('<h1 id="单信号评估-ic、换手与成本会师" tabindex="-1">单信号评估：IC、换手与成本会师 <a class="header-anchor" href="#单信号评估-ic、换手与成本会师" aria-label="Permalink to &quot;单信号评估：IC、换手与成本会师&quot;">​</a></h1><div class="epigraph"><p>信息比率近似等于信息系数乘以广度的平方根——手艺与运气的区别，就藏在这两个量的分解里。</p><footer>—— 据 Grinold (1989) 的主动管理基本定律；Grinold and Kahn《主动投资组合管理》整理</footer></div><p><a href="/quant/signal-construction-sandbox">上一课</a>把直觉翻译成通过健康检查的可计算量。本课是全单元的会师：IC 与分层收益度量信号质量，换手与成本度量它的可实现性，两侧第一次落进同一张数字表。度量工具在 <a href="/quant/ic-ir-timing">IC / IR 与因子择时</a>与 <a href="/quant/ir-sharpe">IR / Sharpe / Sortino</a> 备好，成本侧的<a href="/quant/spread-cost">买卖价差成本</a>与<a href="/quant/sqrt-impact">线性与平方根冲击</a>备好；本课把它们接成一次完整评估。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>健康检查通过只说明信号「是个东西」，不说明它值钱。值不值钱由四组数共同决定：预测质量（IC 多高、稳不稳）、实现载体（分层收益是否单调、两端谁贡献）、实现成本（换手多少、每单位换手付多少）、可扩展性（容量多大）。文献里只报告第一组的研究随处可见，也因此实盘失效得随处可见：IC 0.05、年换手百分之几百的信号，在中位价差面前是负的。会师的意思是：四组数放进同一张表，缺一组别下结论。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>评估表按序产出。<strong>IC 序列</strong>：每个截面期算 Spearman 秩相关 \\(\\mathrm{IC}_t=\\mathrm{corr}(s_{i,t},r_{i,t+h})\\)，报告均值、标准差（ICIR）与 t 值；重叠持有期按<a href="/quant/label-horizon-overlap">标签、预测期与重叠</a>修正序列相关。经验锚点：主动管理的 IC 常年在 0.05 量级（Grinold 与 Kahn 的口径），再低要先怀疑度量噪声。<strong>分层收益</strong>：十分组多空看单调性与两端贡献；PEAD 的收益集中在公告后窗口，按事件对齐比按日历对齐诚实。<strong>换手与衰减</strong>：信号自相关给出换手下限，衰减曲线见<a href="/quant/factor-decay-turnover">因子衰减与换手</a>；年换手 \\(\\tau\\) 乘单位成本 \\(c\\) 是年度拖累。<strong>成本会师</strong>：净信息比约为毛信息比减拖累折算；再平衡发生在「多持有一天的衰减」小于「等待省下的成本」处，框架见<a href="/quant/holding-horizon">持有期与换手</a>。<strong>子样本稳定性</strong>：上下半样本、分年度、分市场状态各跑一遍，门槛是符号与量级稳定，不是每段都显著。<strong>门槛</strong>：为组合化立准入线——例如净 IR 不低于 0.5、容量不小于目标规模、衰减半衰期不短于持有期——门槛本身写进注册文档。</p><p><span class="marginnote">Grinold 与 Kahn 的量级感：IC=0.05、每年 100 次独立下注，IR 约等于 0.5——比直觉低得多。广度按独立下注次数计，不按持仓只数计：高度重叠的持有期不增加广度。</span></p><p><span class="marginnote">Spearman 秩相关就是先排名次再算相关：不管信号值是 3.2 还是 320，只看它把每只股票排在第几名。IC 用它是因为我们只关心「谁比谁好」的次序预测得对不对，不关心数值本身的大小——这也让它和上一课的 rank 变换天然配套。</span></p><p><span class="marginnote">数字代入拖累公式：年换手 \\(\\tau=3\\)（一年把组合整体买卖三轮）、单位成本 \\(c=0.5\\%\\)（价差加冲击合计），年度拖累就是 \\(3\\times0.5\\%=1.5\\%\\)。IC 0.05 的信号一年辛苦攒下的超额收益往往也就百分之几，拖累一项就吃掉一小半——这是「回测有 alpha、实盘变负」最常见的来路。</span></p><h3 id="会师表的读法" tabindex="-1">会师表的读法 <a class="header-anchor" href="#会师表的读法" aria-label="Permalink to &quot;会师表的读法&quot;">​</a></h3>',11)),(n(),i(l,null,{default:r(()=>[o(e,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SIG%5B%22%E4%BF%A1%E5%8F%B7%E5%BA%8F%E5%88%97%22%5D%20--%3E%20IC%5B%22IC%20%2F%20ICIR%20%2F%20%E5%88%86%E5%B1%82%E5%8D%95%E8%B0%83%E6%80%A7%22%5D%0A%20%20SIG%20--%3E%20AC%5B%22%E8%87%AA%E7%9B%B8%E5%85%B3%20%E2%86%92%20%E6%8D%A2%E6%89%8B%E4%B8%8B%E9%99%90%22%5D%0A%20%20AC%20--%3E%20COST%5B%22%E5%B9%B4%E6%8D%A2%E6%89%8B%20%C3%97%20%E5%8D%95%E4%BD%8D%E6%88%90%E6%9C%AC%20%2B%20%E5%86%B2%E5%87%BB%22%5D%0A%20%20IC%20--%3E%20NET%5B%22%E5%87%80%E8%BE%B9%E9%99%85%20%3D%20%E6%AF%9B%E4%BF%A1%E6%81%AF%20%E2%88%92%20%E6%8B%96%E7%B4%AF%22%5D%0A%20%20COST%20--%3E%20NET%0A%20%20NET%20--%3E%20SUB%7B%22%E5%AD%90%E6%A0%B7%E6%9C%AC%EF%BC%9A%E7%AC%A6%E5%8F%B7%E4%B8%8E%E9%87%8F%E7%BA%A7%E7%A8%B3%E5%AE%9A%22%7D%0A%20%20SUB%20--%3E%7C%E8%BF%87%7C%20GATE%5B%22%E7%BB%84%E5%90%88%E5%8C%96%E9%97%A8%E6%A7%9B%EF%BC%9A%E5%87%80%20IR%20%2F%20%E5%AE%B9%E9%87%8F%20%2F%20%E5%8D%8A%E8%A1%B0%E6%9C%9F%22%5D%0A%20%20SUB%20--%3E%7C%E4%B8%8D%E8%BF%87%7C%20STOP%5B%22%E7%BB%88%E6%AD%A2%E6%88%96%E9%99%8D%E7%BA%A7%E4%B8%BA%E6%8E%A2%E7%B4%A2%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,"对案例：毛侧 IC 0.04、ICIR 0.35、分层单调，看起来活着；成本侧年换手两倍多，拖累把净 IR 压到门槛附近。毛指标活着不等于净指标达标——缩水后还站不站得住，是下一课的清算。",-1)),a[4]||(a[4]=t("h2",{id:"机制",tabindex:"-1"},[E("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=t("p",null,[E("IC 与收益的桥是 Grinold 的预测方程：信号 z 分数乘以 IC 与波动，得到条件预期收益；\\(\\mathrm{IR}\\approx\\mathrm{IC}\\sqrt{\\mathrm{BR}}\\)，广度 BR 是每年独立的下注次数。会师的机制含义：IC 决定每次下注的边际，换手与成本决定下注频率的定价——高频下注的便宜 IC 会被 \\(\\tau c\\) 吃光；衰减曲线给出最优频率的内点，太慢吃不满衰减前的信号，太快为同一份信息重复付费。子样本稳定性检验的是「会师表」在时间上是否同一张表：参数漂移的信号进组合后无法被风险模型覆盖。容量把会师推到极限：冲击随参与率凸增（平方根律），容量估计按"),t("a",{href:"/quant/live-capacity-estimate"},"实盘容量估计"),E("的口径做，不能用中位价差外推。")],-1)),(n(),i(l,null,{default:r(()=>[o(e,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20ICN%5B%22IC%EF%BC%9A%E6%AF%8F%E6%AC%A1%E4%B8%8B%E6%B3%A8%E7%9A%84%E8%BE%B9%E9%99%85%3Cbr%2F%3E%EF%BC%880.05%20%E9%87%8F%E7%BA%A7%EF%BC%89%22%5D%20--%3E%20GIR%5B%22%E6%AF%9B%20IR%20%E2%89%88%20IC%20%C3%97%20%E2%88%9ABR%22%5D%0A%20%20BRN%5B%22%E5%B9%BF%E5%BA%A6%20BR%EF%BC%9A%E6%AF%8F%E5%B9%B4%E7%8B%AC%E7%AB%8B%E4%B8%8B%E6%B3%A8%E6%AC%A1%E6%95%B0%22%5D%20--%3E%20GIR%0A%20%20TAU%5B%22%E5%B9%B4%E6%8D%A2%E6%89%8B%20%CF%84%22%5D%20--%3E%20DRAG%5B%22%E5%B9%B4%E5%BA%A6%E6%8B%96%E7%B4%AF%20%E2%89%88%20%CF%84%20%C3%97%20c%22%5D%0A%20%20CN%5B%22%E5%8D%95%E4%BD%8D%E6%88%90%E6%9C%AC%20c%EF%BC%9A%E4%BB%B7%E5%B7%AE%20%2B%20%E5%86%B2%E5%87%BB%22%5D%20--%3E%20DRAG%0A%20%20GIR%20--%3E%20NET%5B%22%E5%87%80%20IR%20%E2%89%88%20%E6%AF%9B%20IR%20%E2%88%92%20%E6%8B%96%E7%B4%AF%E6%8A%98%E7%AE%97%22%5D%0A%20%20DRAG%20--%3E%20NET%0A%20%20NET%20--%3E%20GATE%7B%22%E5%87%80%20IR%20%E8%BF%87%E7%BB%84%E5%90%88%E5%8C%96%E9%97%A8%E6%A7%9B%EF%BC%9F%22%7D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=B('<p><span class="marginnote">衰减半衰期就是信号预测力掉到一半所用的时间：若半衰期是 20 天而持有期设 60 天，最后 40 天你拿着的基本是个「过期」信号。所以门槛里要求「半衰期不短于持有期」——拿过期信号调仓，等于为同一份旧信息反复付费，正是图中 \\(\\tau c\\) 拖累的另一种形态。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>IC 是单调性度量，看不见非线性与尾部：只在极端十分位有效的信号要靠分层与分段暴露补。成本模型是估计不是事实，市场状态一变（价差放大、深度坍缩）拖累项重写，评估须附<a href="/quant/cost-sensitivity">费用、滑点敏感性</a>。子样本稳定也不担保未来：它排除的是最粗的脆弱性，机制环境改变仍会让衰减加速。门槛是入场券不是保证书：净指标达标只说明这个信号<strong>作为独立下注</strong>成立；它与既有持仓的相关、拥挤与对冲残差，本课刻意不回答——那是下一单元的事。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>评估是四组数的会师：IC/ICIR、分层单调性、换手乘成本、容量；缺一不可。</li><li>IC 的经验量级 0.05；IR 与广度的关系由基本定律给出，成本把频率的红利收回。</li><li>再平衡发生在边际衰减小于边际成本节省之处。</li><li>子样本稳定性看符号与量级；门槛（净 IR、容量、半衰期）写进注册文档。</li><li>毛指标活着不等于净指标达标；缩水判定留给多重检验课。</li><li>出处：Grinold (1989) 基本定律与 Grinold–Kahn 预测方程；成本与冲击见站内价差、平方根律诸课。</li></ul>',5))])}const g=s(d,[["render",I]]);export{F as __pageData,g as default};
